import json,re,glob
from collections import Counter
_WS=re.compile(r'\s+')
def norm(c): return _WS.sub(' ',c.strip())
for f in sorted(glob.glob('*.messages.json')):
    msgs=json.load(open(f))
    cmds=[]
    for m in msgs:
        for tc in (m.get('tool_calls') or []):
            fn=tc.get('function',{})
            if fn.get('name')=='Bash':
                try: a=json.loads(fn.get('arguments','{}'))
                except: a={}
                cmds.append(norm(a.get('command','')))
    c=Counter(cmds)
    if c:
        cmd,n=c.most_common(1)[0]
        if n>=5:
            r=json.load(open(f.replace('.messages.json','.result.json')))
            print('reward=%s max-repeat=%d  %s  cmd=%s'%(r['reward'],n,f[:22],cmd[:70]))
